export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export type ValidationResult = { ok: true; payload: Payload } | { ok: false; fields: FieldError[] };

const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** The payload as a stable string, used to compare idempotent submissions. */
export function canonicalPayload(p: Payload): string {
  return JSON.stringify({ input: p.input, steps: p.steps, failAttempts: p.failAttempts });
}

/**
 * Validates a job submission. Every problem found is reported, so the caller can name each
 * offending field. Validation does not depend on the database.
 */
export function validateSubmission(contentType: string | undefined, rawBody: string, idemKey: string | undefined): ValidationResult {
  const fields: FieldError[] = [];
  if (idemKey !== undefined && !KEY_PATTERN.test(idemKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 letters, digits, "_" or "-"' });
  }

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
    return { ok: false, fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }
  const body = parsed as Record<string, unknown>;

  for (const key of Object.keys(body)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const input = body.input;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  }

  const steps = integerField(body.steps, 'steps', 5, 1, 20, fields);
  const failAttempts = integerField(body.failAttempts, 'failAttempts', 0, 0, 5, fields);

  if (fields.length > 0 || typeof input !== 'string' || steps === undefined || failAttempts === undefined) {
    return { ok: false, fields };
  }
  return { ok: true, payload: { input, steps, failAttempts } };
}

function integerField(value: unknown, name: string, def: number, min: number, max: number, fields: FieldError[]): number | undefined {
  if (value === undefined) return def;
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: 'must be an integer' });
    return undefined;
  }
  if (value < min || value > max) {
    fields.push({ field: name, message: `must be between ${min} and ${max}` });
    return undefined;
  }
  return value;
}

