import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, rowToJob, type Job, type JobRow } from './db.ts';
import { canonicalPayload, validateSubmission, type FieldError } from './validate.ts';

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_FRESH_MS = 3000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectJobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectAllJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectIdempotency = db.prepare('SELECT payload, job_id FROM idempotency_keys WHERE idem_key = ?');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, run_after, lease_until, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, 0, ?, ?)`,
);
const insertIdempotency = db.prepare('INSERT INTO idempotency_keys (idem_key, payload, job_id) VALUES (?, ?, ?)');
const selectHeartbeat = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

/** Returns true if `method` is allowed; otherwise sends 405 and returns false. */
function allowMethod(res: ServerResponse, method: string, allowed: string[]): boolean {
  if (allowed.includes(method)) return true;
  res.setHeader('allow', allowed.join(', '));
  sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here`);
  return false;
}

function getJobRow(id: string): JobRow | undefined {
  return selectJobById.get(id) as unknown as JobRow | undefined;
}

function handleCreate(req: IncomingMessage, res: ServerResponse, raw: string): void {
  const rawKey = req.headers['idempotency-key'];
  const idemKey = typeof rawKey === 'string' ? rawKey : undefined;
  const result = validateSubmission(req.headers['content-type'], raw, idemKey);
  if (!result.ok) {
    sendError(res, 400, 'invalid_request', 'Invalid request', result.fields);
    return;
  }

  const payload = result.payload;
  const canonical = canonicalPayload(payload);
  let outcome: { status: number; job?: Job; conflict?: boolean };

  // One IMMEDIATE transaction covers the key lookup and the insert, so two racing submissions with
  // the same key cannot both create a job.
  db.exec('BEGIN IMMEDIATE');
  try {
    outcome = { status: 201 };
    const existing = idemKey === undefined ? undefined : (selectIdempotency.get(idemKey) as { payload: string; job_id: string } | undefined);
    if (existing) {
      if (existing.payload === canonical) {
        outcome = { status: 200, job: rowToJob(getJobRow(existing.job_id)!) };
      } else {
        outcome = { status: 409, conflict: true };
      }
    } else {
      const now = new Date().toISOString();
      const id = randomUUID();
      insertJob.run(id, payload.input, payload.steps, payload.failAttempts, now, now);
      if (idemKey !== undefined) insertIdempotency.run(idemKey, canonical, id);
      outcome = { status: 201, job: rowToJob(getJobRow(id)!) };
    }
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open
    }
    throw e;
  }

  if (outcome.conflict) {
    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
  } else {
    sendJson(res, outcome.status, outcome.job);
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  // HEAD is answered like GET; Node omits the body for HEAD responses.
  const method = req.method === 'HEAD' ? 'GET' : (req.method ?? 'GET');

  if (path === '/') {
    if (!allowMethod(res, method, ['GET'])) return;
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    if (!allowMethod(res, method, ['GET'])) return;
    const hb = selectHeartbeat.get() as { at: number } | undefined;
    const up = hb !== undefined && Date.now() - hb.at < WORKER_FRESH_MS;
    sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (!allowMethod(res, method, ['GET', 'POST'])) return;
    if (method === 'POST') {
      const raw = await readBody(req);
      handleCreate(req, res, raw);
      return;
    }
    const jobs = (selectAllJobs.all() as unknown as JobRow[]).map(rowToJob);
    sendJson(res, 200, { jobs });
    return;
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (!allowMethod(res, method, ['GET'])) return;
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      sendError(res, 404, 'not_found', 'No such job');
      return;
    }
    const row = getJobRow(id);
    if (!row) {
      sendError(res, 404, 'not_found', 'No such job');
      return;
    }
    sendJson(res, 200, rowToJob(row));
    return;
  }

  sendError(res, 404, 'not_found', 'No such route');
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error');
    else res.end();
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  const finish = (): void => {
    try {
      db.close();
    } catch {
      // already closed
    }
    process.exit(0);
  };
  server.close(finish);
  server.closeAllConnections();
  // Fallback in case something keeps the server from closing.
  setTimeout(finish, 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.on('error', (e) => {
  console.error(`server failed: ${e.message}`);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

