import { setInterval, clearInterval } from 'node:timers';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 100;
const RETRY_DELAY_MS = 500;
const LEASE_MS = 3000;
const HEARTBEAT_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

const selectClaimable = db.prepare(
  `SELECT * FROM jobs
   WHERE (status = 'queued' AND run_after <= ?) OR (status = 'running' AND lease_until < ?)
   ORDER BY seq ASC LIMIT 1`,
);
const claimJob = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = ?, progress = 0, output = NULL, error = NULL,
     lease_until = ?, updated_at = ? WHERE seq = ?`,
);
const setProgress = db.prepare(
  `UPDATE jobs SET progress = ?, lease_until = ?, updated_at = ? WHERE seq = ? AND status = 'running'`,
);
const requeueJob = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, lease_until = 0, updated_at = ?
   WHERE seq = ? AND status = 'running'`,
);
const failJob = db.prepare(
  `UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, progress = 0,
     lease_until = 0, updated_at = ? WHERE seq = ? AND status = 'running'`,
);
const completeJob = db.prepare(
  `UPDATE jobs SET status = 'completed', output = ?, progress = steps, lease_until = 0, updated_at = ?
   WHERE seq = ? AND status = 'running'`,
);
const writeHeartbeat = db.prepare('INSERT OR REPLACE INTO heartbeat (id, at) VALUES (1, ?)');

const nowIso = (): string => new Date().toISOString();

function beat(at: number): void {
  writeHeartbeat.run(at);
}

/** Atomically claims the oldest runnable job and records a new attempt. */
function claimNext(): { job: JobRow; attempt: number } | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const now = Date.now();
    const job = selectClaimable.get(now, now) as unknown as JobRow | undefined;
    if (!job) {
      db.exec('COMMIT');
      return undefined;
    }
    const attempt = job.attempts + 1;
    claimJob.run(attempt, now + LEASE_MS, nowIso(), job.seq);
    db.exec('COMMIT');
    return { job, attempt };
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open
    }
    throw e;
  }
}

/** Runs one attempt of a job: simulated failure, or steps with progress written after each one. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt <= job.fail_attempts) {
    // Fail at the first step, before any progress is made.
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) {
      failJob.run(nowIso(), job.seq);
    } else {
      requeueJob.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.seq);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Shutting down: hand the job back so it is processed again from the start after restart.
      requeueJob.run(0, nowIso(), job.seq);
      return;
    }
    const res = setProgress.run(step, Date.now() + LEASE_MS, nowIso(), job.seq);
    if (res.changes === 0) return; // the job was changed by someone else; leave it alone
  }

  completeJob.run(job.input.toUpperCase(), nowIso(), job.seq);
}

async function main(): Promise<void> {
  for (const signal of ['SIGINT', 'SIGTERM'] as const) {
    process.on(signal, () => {
      stopping = true;
    });
  }

  // Only the worker reclaims jobs left `running` by a crashed worker. The job is queued again
  // immediately and its next attempt counts as a new attempt.
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, lease_until = 0, updated_at = ?
     WHERE status = 'running'`,
  ).run(nowIso());

  beat(Date.now());
  const heartbeat = setInterval(() => beat(Date.now()), HEARTBEAT_MS);

  console.log('worker started');
  while (!stopping) {
    let claimed: { job: JobRow; attempt: number } | undefined;
    try {
      claimed = claimNext();
    } catch (e) {
      console.error('claim failed:', e);
      await sleep(500);
      continue;
    }
    if (!claimed) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    try {
      await runAttempt(claimed.job, claimed.attempt);
    } catch (e) {
      // The job stays `running` with an expiring lease and is reclaimed later.
      console.error('attempt failed:', e);
      await sleep(500);
    }
  }

  clearInterval(heartbeat);
  beat(0); // report the worker as down right away
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

